{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Loganin, the closest structural analogue (Morgan 0.7857), showed difficulty crossing the BBB in rat tissue distribution, with the lowest brain levels after systemic administration; this directly supports poor CNS access for the similarly polar iridoid glycoside core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Geniposide, a moderately similar iridoid glycoside (Morgan 0.629), was detected in rat brain microdialysates and tissue homogenates, demonstrating that some iridoid glycosides can cross the BBB; this provides a contradictory line of evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Gastrodin, despite being detected in brain, had a CSF/plasma ratio of only 5.5% in rats, illustrating that brain detection alone does not establish meaningful CNS exposure and supporting a fail interpretation for very hydrophilic glycosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: fail. The closest analogue loganin (Morgan 0.7857) is experimentally impermeable across the BBB, and the query's additional ether oxygen makes it even more polar; although some less-similar iridoid glycosides such as geniposide are detectable in brain, the strongest transferable evidence and physicochemical prior point to inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic data are available for morroniside itself.",
    "Whether morroniside is a substrate for BBB uptake or efflux transporters is unknown.",
    "Quantitative brain exposure measures (e.g., Kp, AUC ratio) are lacking for the closest analogue loganin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

